using System.Reflection;
using Microsoft.CodeAnalysis;
using Microsoft.CodeAnalysis.CSharp;
using Microsoft.CodeAnalysis.Diagnostics;
using Microsoft.CodeAnalysis.Testing;

namespace Receipts.GeneratedTests;

public class SuppressSourceGenerationAnalyzerReceiptTests
{
    private static ImmutableArray<DiagnosticAnalyzer> GetAnalyzers()
    {
        return typeof(MessagePack.SourceGenerator.MessagePackGenerator).Assembly
            .GetTypes()
            .Where(t => !t.IsAbstract
                && typeof(DiagnosticAnalyzer).IsAssignableFrom(t)
                && t.GetCustomAttribute<DiagnosticAnalyzerAttribute>() is not null
                && t.GetConstructor(Type.EmptyTypes) is not null)
            .Select(t => (DiagnosticAnalyzer)Activator.CreateInstance(t)!)
            .ToImmutableArray();
    }

    private static async Task<(ImmutableArray<Diagnostic> Diagnostics, List<Exception> Exceptions)> AnalyzeAsync(string source)
    {
        ImmutableArray<MetadataReference> frameworkRefs = await ReferenceAssemblies.Net.Net80.ResolveAsync(LanguageNames.CSharp, CancellationToken.None);
        IEnumerable<MetadataReference> messagePackRefs = ReferencesHelper.GetReferences(ReferencesSet.MessagePack);
        CSharpCompilation compilation = CSharpCompilation.Create(
            "ReceiptsSuppressedAnalysis",
            new[] { CSharpSyntaxTree.ParseText(source, new CSharpParseOptions(LanguageVersion.Latest)) },
            frameworkRefs.Concat(messagePackRefs),
            new CSharpCompilationOptions(OutputKind.DynamicallyLinkedLibrary));

        ImmutableArray<DiagnosticAnalyzer> analyzers = GetAnalyzers();
        Assert.NotEmpty(analyzers);

        var exceptions = new List<Exception>();
        var options = new CompilationWithAnalyzersOptions(
            new Microsoft.CodeAnalysis.Diagnostics.AnalyzerOptions(ImmutableArray<AdditionalText>.Empty),
            (ex, analyzer, diag) => { lock (exceptions) { exceptions.Add(ex); } },
            concurrentAnalysis: false,
            logAnalyzerExecutionTime: false);

        CompilationWithAnalyzers withAnalyzers = compilation.WithAnalyzers(analyzers, options);
        ImmutableArray<Diagnostic> diagnostics = await withAnalyzers.GetAnalyzerDiagnosticsAsync(CancellationToken.None);
        return (diagnostics, exceptions);
    }

    [Fact]
    public async Task DuplicateIntKeys_SuppressedType_ReportsDiagnosticWithoutCrash()
    {
        string source = """
            using MessagePack;

            namespace TestNs
            {
                [MessagePackObject(SuppressSourceGeneration = true)]
                public class DupKeys
                {
                    [Key(0)]
                    public int A { get; set; }

                    [Key(0)]
                    public int B { get; set; }
                }
            }
            """;

        var (diagnostics, exceptions) = await AnalyzeAsync(source);

        Assert.Empty(exceptions);
        Assert.DoesNotContain(diagnostics, d => d.Id == "AD0001");

        int typeStart = source.IndexOf("public class DupKeys", StringComparison.Ordinal);
        Assert.Contains(diagnostics, d => d.Id.StartsWith("MsgPack", StringComparison.Ordinal)
            && d.Location.IsInSource
            && d.Location.SourceSpan.Start >= typeStart);
    }

    [Fact]
    public async Task DuplicateStringKeys_SuppressedType_OtherViolationsStillReported()
    {
        string source = """
            using MessagePack;

            namespace TestNs
            {
                [MessagePackObject(SuppressSourceGeneration = true)]
                public class DupStringKeys
                {
                    [Key("x")]
                    public int A { get; set; }

                    [Key("x")]
                    public int B { get; set; }
                }

                [MessagePackObject(SuppressSourceGeneration = true)]
                public class MissingKey
                {
                    [Key(0)]
                    public int A { get; set; }

                    public int NoKey { get; set; }
                }
            }
            """;

        var (diagnostics, exceptions) = await AnalyzeAsync(source);

        Assert.Empty(exceptions);
        Assert.DoesNotContain(diagnostics, d => d.Id == "AD0001");
        Assert.Contains(diagnostics, d => d.Id == "MsgPack004");
    }
}
